        var a=Actor(s);var g=_chapter.CurrentGeometry(s)[Contract.Scene];Require(a.Scene==g.Id&&a.Position.Distance(g.Spots.Single(x=>x.Id==Contract.Spot).Stand)<=2.5&&new NavigationGrid(g).CanStand(a.Position,true),"请先实际到外线原检修安全站位。");
