    private FieldRelayState State(BranchSnapshot s,bool unfinished=true)
    {var st=Read<FieldRelayState>(s,StateId)??throw new InvalidOperationException("尚未明确接受该局部检修范围。");Require(st.Instance!=Guid.Empty&&st.SourceFingerprint==Contract.Fingerprint&&st.ScopeDecision=="accept"&&(!unfinished||!st.Completed),"当前旁修许可、源版本或状态不符。");Require(s.Items.Any(i=>i.Id==Contract.RelaySerial&&i.DefinitionId=="R6-AUX-RELAY"&&i.OwnerKind==(st.Repaired?"installed":"warehouse")&&i.OwnerId==(st.Repaired?"R6-S06:auxiliary-fixture":"R6-S06:auxiliary-watch")),"同一当地辅机当前保管地不符，不能另机替代。");Require(s.Items.Any(i=>i.Id==Contract.PinSerial&&i.DefinitionId=="R6-AUX-BRAKE-PIN"&&(i.OwnerKind=="warehouse"&&i.OwnerId=="R6-S06:auxiliary-watch"&&!st.Repaired&&st.ZeroCheck is null||i.OwnerKind=="installed"&&i.OwnerId==Contract.RelaySerial)),"专用销的当前实物、当地保管地或固定状态不符。");return st;}
