    private static FieldRelayGauge Gauge(FieldRelayState? st,string serial,string channel)=>new(serial,channel,channel=="REF"?10:st?.AuxSwitch=="OFF"?0:18,st?.Configuration??0,st?.AuxSwitch=="OFF",false);
    private FieldRelayGauge CurrentGauge(BranchSnapshot s,string channel)
