    private string[] Reads(BranchSnapshot s)=>s.Entities.Select(e=>e.Id).Concat(new[]{StateId,CombatId,"R6:result:"+Encounter,"material:"+MaterialId,StateId+":zero",StateId+":return",StateId+":completion","final:preparation"}).Distinct().ToArray();
    private CommitPlanCommand Plan(BranchSnapshot s,string key,string action,object payload,ImmutableArray<EntityChange> changes=default,ImmutableArray<ItemChange> items=default,CommandId? command=null)
    {
        var claims=(items.IsDefault?ImmutableArray<ItemChange>.Empty:items).ToBuilder();
        foreach(var item in s.Items.Where(i=>i.Id==Contract.RelaySerial||i.Id==Contract.PinSerial))
            if(!claims.Any(c=>c.Id==item.Id))claims.Add(new(item.Id,item.DefinitionId,item.OwnerKind,item.OwnerId,item.OwnerKind,item.OwnerId,item.Slot));
        return BranchOperations.Plan(_repository,s,key,action,changes.IsDefault?[]:changes,Reads(s),payload,items:claims.ToImmutable(),request:command);
    }
    private async ValueTask<CommandResult> Execute(CommitPlanCommand c)
    {var session=_repository.Session;if(c.Context.Profile!=session.Profile||c.Context.Branch!=session.Branch||c.Context.Load!=session.Load||c.Context.ReleaseId!=session.ReleaseId)return new(CommitStatus.Rejected,null,[new("stale_load",StateId,"读取世代改变，请重新核对当前维修。")]);if(_repository is not IEventLeaseStore leases)throw new InvalidOperationException("现场旁修需要原子前景占用。");string owner="field-relay:"+c.Context.Command.Value;Require(await leases.TryLeasesAsync(c.Context.Load,owner,["input:foreground"]),"另一前景工作尚未交接。");try{return await _repository.ExecuteAsync(c);}finally{await leases.ReleaseLeasesAsync(c.Context.Load,owner);}}
